    edit(row) { this.editing = this.tab === 'events' ? row.id_event : (this.tab === 'speakers' ? row.id_speaker : row.id_schedule); this.formError = ''; if (this.tab === 'events') this.eventForm = { nama_event: row.nama_event, tema: row.tema || '', deskripsi: row.deskripsi || '', tanggal_mulai: (row.tanggal_mulai || '').slice(0,10), tanggal_selesai: (row.tanggal_selesai || '').slice(0,10), lokasi: row.lokasi || '', mode_kegiatan: row.mode_kegiatan, status_event: row.status_event }; else if (this.tab === 'speakers') this.speakerForm = { id_event: row.id_event, nama_speaker: row.nama_speaker, institusi: row.institusi || '', negara: row.negara || '', deskripsi: row.deskripsi || '', foto_url: row.foto_url || '' }; else this.scheduleForm = { id_event: row.id_event, nama_kegiatan: row.nama_kegiatan, tanggal: (row.tanggal || '').slice(0,10), waktu_mulai: (row.waktu_mulai || '').slice(0,5), waktu_selesai: (row.waktu_selesai || '').slice(0,5), lokasi: row.lokasi || '', deskripsi: row.deskripsi || '' }; this.modal = true; },
    async save() { this.saving = true; this.formError = ''; const payload = this.tab === 'events' ? this.eventForm : (this.tab === 'speakers' ? this.speakerForm : this.scheduleForm); const endpoint = this.endpoints[this.tab] + (this.editing ? '/' + this.editing : ''); let result; if (this.tab === 'speakers') { const fd = new FormData(); ['id_event', 'nama_speaker', 'institusi', 'negara', 'deskripsi'].forEach(k => fd.append(k, payload[k] ?? '')); const file = this.$refs.speakerPhoto?.files?.[0]; if (file) fd.append('foto', file); result = await window.asicApi.upload(endpoint, fd); } else { result = this.editing ? await window.asicApi.patch(endpoint, payload) : await window.asicApi.post(endpoint, payload); } this.saving = false; if (!result.ok) { this.formError = result.error || Object.values(result.errors || {}).flat().join(' '); return; } this.modal = false; await this.load(); },
    async remove(row) { const id = this.tab === 'events' ? row.id_event : (this.tab === 'speakers' ? row.id_speaker : row.id_schedule); if (!confirm(i18n.confirm_delete)) return; const result = await window.asicApi.delete(this.endpoints[this.tab] + '/' + id); if (!result.ok) { this.error = result.error || i18n.delete_failed; return; } await this.load(); }
